class LmdbPhysicalJoinOrderOptionalTest {

	private static final String EX = "http://example.com/";

	private static final String QUERY = "PREFIX ex: <" + EX + ">\n"
			+ "SELECT DISTINCT ?q ?eid ?g WHERE {\n"
			+ "  ?p a ex:Proc ; ex:hasConfig ?c .\n"
			+ "  ?c ex:mapsToQueue ?q .\n"
			+ "  OPTIONAL {\n"
			+ "    ?q ex:updates ?e . ?e ex:id ?eid .\n"
			+ "    OPTIONAL { ?e ex:mappedTo ?f . ?f ex:group ?g . }\n"
			+ "  }\n"
			+ "}";

	@Test
	void outerOptionalStartsWithPatternConsumingOuterBinding() {
		TupleExpr expr = optimize();
		LeftJoin outer = leftJoinBinding(expr, "eid");
		assertThat(firstPattern(outer.getRightArg()).getPredicateVar().getValue().stringValue())
				.as(expr.toString())
				.isEqualTo(EX + "updates");
	}

	@Test
	void nestedOptionalStartsWithPatternConsumingEnclosingBinding() {
		TupleExpr expr = optimize();
		LeftJoin nested = leftJoinBinding(expr, "g");
		assertThat(firstPattern(nested.getRightArg()).getPredicateVar().getValue().stringValue())
				.as(expr.toString())
				.isEqualTo(EX + "mappedTo");
	}

	@Test
	void costEstimateOfOptionalPatternAccountsForOuterBinding() {
		TupleExpr expr = optimize();
		List<StatementPattern> updates = new ArrayList<>();
		expr.visit(new AbstractSimpleQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern node) {
				if (node.getPredicateVar().hasValue()
						&& node.getPredicateVar().getValue().stringValue().equals(EX + "updates")) {
					updates.add(node);
				}
			}
		});
		assertThat(updates).as(expr.toString()).hasSize(1);
		assertThat(updates.get(0).getCostEstimate()).as(expr.toString()).isLessThan(198900.0d);
	}

	private static final String BIND_QUERY = "PREFIX ex: <" + EX + ">\n"
			+ "SELECT ?q ?eid ?x WHERE {\n"
			+ "  ?p a ex:Proc ; ex:hasConfig ?c .\n"
			+ "  ?c ex:mapsToQueue ?q .\n"
			+ "  OPTIONAL { BIND(1 AS ?x) ?q ex:updates ?e . ?e ex:id ?eid . }\n"
			+ "}";

	@Test
	void optionalWithLeadingPriorityArgStillReordersStatementPatternRun() {
		// QueryJoinOptimizer emits Join(<priority arg>, Join(patterns...)) when the join has a BIND or sub-select.
		// Swap the pattern run into a bad order and check that the physical pass still repairs it.
		TupleExpr expr = optimize(BIND_QUERY);
		LeftJoin optional = leftJoinBinding(expr, "eid");
		Join priorityJoin = (Join) optional.getRightArg();
		assertThat(priorityJoin.getLeftArg()).as(expr.toString()).isInstanceOf(Extension.class);
		Join run = (Join) priorityJoin.getRightArg();
		TupleExpr first = run.getLeftArg();
		TupleExpr second = run.getRightArg();
		first.replaceWith(new SingletonSet());
		second.replaceWith(new SingletonSet());
		run.setLeftArg(second);
		run.setRightArg(first);
		assertThat(((StatementPattern) run.getLeftArg()).getPredicateVar().getValue().stringValue())
				.as(expr.toString())
				.isEqualTo(EX + "id");

		physicalJoinOrderOptimizer().optimize(expr, null, EmptyBindingSet.getInstance());

		LeftJoin after = leftJoinBinding(expr, "eid");
		List<String> predicates = new ArrayList<>();
		after.getRightArg().visit(new AbstractSimpleQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern node) {
				predicates.add(node.getPredicateVar().getValue().stringValue());
			}
		});
		assertThat(predicates).as(expr.toString()).containsExactly(EX + "updates", EX + "id");
	}

	private static QueryOptimizer physicalJoinOrderOptimizer() {
		for (QueryOptimizer optimizer : pipeline().getOptimizers()) {
			if (optimizer.getClass().getSimpleName().equals("LmdbPhysicalJoinOrderOptimizer")) {
				return optimizer;
			}
		}
		throw new AssertionError("physical join order pass missing");
	}

	private static TupleExpr optimize() {
		return optimize(QUERY);
	}

	private static TupleExpr optimize(String query) {
		LmdbStandardQueryOptimizerPipeline pipeline = pipeline();
		List<QueryOptimizer> optimizers = new ArrayList<>();
		pipeline.getOptimizers().forEach(optimizers::add);
		assertThat(optimizers.stream().map(o -> o.getClass().getSimpleName()))
				.contains("LmdbPhysicalJoinOrderOptimizer");

		TupleExpr expr = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
		for (QueryOptimizer optimizer : optimizers) {
			optimizer.optimize(expr, null, EmptyBindingSet.getInstance());
		}
		return expr;
	}

	private static LmdbStandardQueryOptimizerPipeline pipeline() {
		EvaluationStatistics stats = new EvaluationStatistics() {
			@Override
			public double getCardinality(TupleExpr expr) {
				if (expr instanceof StatementPattern pattern && pattern.getPredicateVar().hasValue()) {
					String p = pattern.getPredicateVar().getValue().stringValue();
					if (p.equals(RDF.TYPE.stringValue())) {
						return 6200;
					} else if (p.equals(EX + "hasConfig")) {
						return 31000;
					} else if (p.equals(EX + "mapsToQueue")) {
						return 31300;
					} else if (p.equals(EX + "updates")) {
						return 198900;
					} else if (p.equals(EX + "id")) {
						return 146800;
					} else if (p.equals(EX + "mappedTo")) {
						return 15700;
					} else if (p.equals(EX + "group")) {
						return 110;
					}
				}
				return super.getCardinality(expr);
			}
		};
		TripleSource tripleSource = new EmptyTripleSource();
		EvaluationStrategy strategy = new DefaultEvaluationStrategyFactory().createEvaluationStrategy((Dataset) null,
				tripleSource, stats, QueryExecutionPolicy.EXPERIMENTAL);
		return new LmdbStandardQueryOptimizerPipeline(strategy, tripleSource, stats);
	}

	private static LeftJoin leftJoinBinding(TupleExpr expr, String name) {
		List<LeftJoin> found = new ArrayList<>();
		expr.visit(new AbstractSimpleQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(LeftJoin node) {
				if (node.getRightArg().getBindingNames().contains(name)) {
					found.add(node);
				}
				super.meet(node);
			}
		});
		assertThat(found).as(expr.toString()).isNotEmpty();
		// innermost LeftJoin whose right arg binds the variable
		return found.get(found.size() - 1);
	}

	private static StatementPattern firstPattern(TupleExpr expr) {
		TupleExpr current = expr;
		while (true) {
			if (current instanceof StatementPattern pattern) {
				return pattern;
			} else if (current instanceof Join join) {
				current = join.getLeftArg();
			} else if (current instanceof LeftJoin leftJoin) {
				current = leftJoin.getLeftArg();
			} else {
				throw new AssertionError("Unexpected node " + current.getClass() + " in " + expr);
			}
		}
	}

	private static final class EmptyTripleSource implements TripleSource {

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
				Resource... contexts) throws QueryEvaluationException {
			return EMPTY_ITERATION;
		}

		@Override
		public ValueFactory getValueFactory() {
			return SimpleValueFactory.getInstance();
		}
	}
}
